# Builds a privacy-free fixture tree used only for taking documentation screenshots.
#
# Everything under $OutDir is synthetic: generated by FFmpeg's lavfi sources, with
# neutral file names.  Nothing here comes from a real share, so the resulting
# screenshots can be published as-is.
#
#   powershell -NoProfile -ExecutionPolicy Bypass -File scripts/make_doc_media.ps1
param(
    [string]$OutDir = ''
)

$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
if (-not $OutDir) { $OutDir = Join-Path $root 'build\doc-media' }

$ffmpeg = Get-ChildItem (Join-Path $root '.tools\ffmpeg') -Recurse -Filter 'ffmpeg.exe' -File |
    Select-Object -First 1
if (-not $ffmpeg) {
    throw 'ffmpeg.exe not found - run: python tool/fetch_deps.py ffmpeg'
}
$ff = $ffmpeg.FullName

if (Test-Path $OutDir) { Remove-Item -Recurse -Force $OutDir }

function New-Clip {
    param([string]$Path, [int]$Seconds = 3, [string]$Size = '640x360')
    $dir = Split-Path -Parent $Path
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    & $ff -hide_banner -loglevel error -y `
        -f lavfi -i "testsrc2=size=${Size}:rate=25" `
        -f lavfi -i "sine=frequency=440:sample_rate=48000" `
        -t $Seconds -c:v libx264 -preset ultrafast -pix_fmt yuv420p -c:a aac -shortest `
        $Path
    if ($LASTEXITCODE -ne 0) { throw "ffmpeg failed for $Path" }
}

# --- the share root: five folders, mirroring what the browser shows ---------
$root2 = Join-Path $OutDir 'share'
foreach ($d in @('downloads', 'animation', 'clips', 'music', 'movies')) {
    New-Item -ItemType Directory -Force -Path (Join-Path $root2 $d) | Out-Null
}

# --- a folder of .flv files plus one .docx ---------------------------------
# This is the "mixed folder" screenshot: the browser must hide the .docx and
# keep the sixteen videos.
$flv = Join-Path $root2 'clips'
$titles = @(
    '01 gigabit-in-practice.flv',
    '02 cabling-standards.flv',
    '03 switch-vs-hub.flv',
    '04 multicast-basics.flv',
    '05 wireless-interference.flv',
    '06 bandwidth-vs-latency.flv',
    '07 buffer-sizing.flv',
    '08 nat-traversal.flv',
    '09 tcp-or-udp.flv',
    '10 audio-video-sync.flv',
    '11 hardware-vs-software.flv',
    '12 colour-space-roundtrip.flv',
    '13 subtitle-track-shapes.flv',
    '14 container-and-index.flv',
    '15 seek-precision.flv',
    '16 thumbnails-on-demand.flv'
)
$i = 0
foreach ($t in $titles) {
    $i++
    $p = Join-Path $flv $t
    New-Clip -Path $p -Seconds 2
}
# a document sitting next to the videos: proves the filter keeps it out
$docx = Join-Path $flv 'notes.docx'
[IO.File]::WriteAllBytes($docx, [byte[]](0x50, 0x4B, 0x03, 0x04))

# --- an anime folder: episodes with sidecar subtitles ----------------------
$anime = Join-Path $root2 'animation\anime-01'
for ($e = 1; $e -le 4; $e++) {
    $name = 'anime-01 - {0:d2}.mkv' -f $e
    New-Clip -Path (Join-Path $anime $name) -Seconds 2
    $srt = @(
        '1', '00:00:00,500 --> 00:00:02,000', "Episode $e (synthetic subtitle)", ''
    ) -join "`r`n"
    [IO.File]::WriteAllText((Join-Path $anime ('anime-01 - {0:d2}.zh.srt' -f $e)), $srt,
        (New-Object System.Text.UTF8Encoding($false)))
}

# --- two videos under movies ----------------------------------------------
New-Clip -Path (Join-Path $root2 'movies\movie-01.mkv') -Seconds 4
New-Clip -Path (Join-Path $root2 'movies\movie-02.mp4') -Seconds 4

Write-Host "== doc media built at $OutDir"
Get-ChildItem -Recurse -File $OutDir |
    Group-Object Extension |
    ForEach-Object { Write-Host ("   {0} {1} file(s)" -f $_.Name, $_.Count) }
